import json,glob,os
for f in glob.glob('factors/*.json'):
 if os.path.basename(f)=='factor_ensemble.json': continue
 try:
  d=json.load(open(f)); print(os.path.basename(f), d.get('status'), d.get('effective'), d.get('metrics',{}), 'IC',d.get('ic'), 'ICIR',d.get('icir'))
 except Exception as e: print('ERR',f,e)
PY

