python - <<'PY'
import csv,glob,os,statistics
for f in glob.glob('../persistent/index_data/*.csv'):
 try:
  rows=list(csv.DictReader(open(f)))[-30:]
  key='close' if 'close' in rows[0] else list(rows[0])[-1]
  vals=[float(r[key]) for r in rows if r.get(key) not in ('',None)]
  if len(vals)>5: print(os.path.basename(f), round((vals[-1]/vals[0]-1)*100,2), round(statistics.pstdev([vals[i]/vals[i-1]-1 for i in range(1,len(vals))])*100,2))
 except: pass
PY

